<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
if(isset($_GET['stage']) && isset($_GET['id']) && is_numeric($_GET['id'])){$id=(int)$_GET['id'];$stage=$_GET['stage'];$allowed=['NEW','CONTACTED','FOLLOW_UP','NEGOTIATING','WON','LOST'];if(in_array($stage,$allowed,true)){car_sales_validate_action_token('lead_stage',$id.'|'.$stage);$st=$conn->prepare('UPDATE leads SET lead_stage=? WHERE id=?');$st->bind_param('si',$stage,$id);$st->execute();set_flash('success','Lead stage updated.');}redirect_to('backend/leads/index.php');}
$stage=trim($_GET['filter']??'');$sql="SELECT l.*,c.car_name,d.name dalali_name FROM leads l LEFT JOIN cars c ON c.id=l.car_id LEFT JOIN dalalis d ON d.id=l.dalali_id";if($stage!==''){$sql.=" WHERE l.lead_stage='".$conn->real_escape_string($stage)."'";}$sql.=' ORDER BY COALESCE(l.next_follow_up, DATE_ADD(CURDATE(),INTERVAL 100 YEAR)), l.created_at DESC';$rows=$conn->query($sql);
$page_title='Sales Leads';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title"><h1 class="page-title">Sales Leads</h1><a class="btn btn-green" href="add.php">Add Lead</a></div><div class="card"><form class="filter-bar"><select name="filter"><option value="">All Stages</option><?php foreach(['NEW','CONTACTED','FOLLOW_UP','NEGOTIATING','WON','LOST'] as $x):?><option <?=$stage===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn">Filter</button><a class="btn btn-dark" href="index.php">Reset</a></form><div class="table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Interested Car</th><th>Source / Dalali</th><th>Budget</th><th>Follow-up</th><th>Stage</th><th>Update</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['customer_name'])?></td><td><?=e($r['phone']?:'—')?></td><td><?=e($r['car_name']?:'Any / Not selected')?></td><td><?=e($r['dalali_name'] ? 'Dalali: '.$r['dalali_name'] : ($r['source']?:'—'))?></td><td><?=($r['budget_min']||$r['budget_max'])?money($r['budget_min']).' - '.money($r['budget_max']):'—'?></td><td><?=e($r['next_follow_up']?:'—')?></td><td><span class="badge stock"><?=e($r['lead_stage'])?></span></td><td><select onchange="if(this.value) location.href=this.value"><option>Change...</option><?php foreach(['CONTACTED','FOLLOW_UP','NEGOTIATING','WON','LOST'] as $x):$u=car_sales_action_url('index.php?id='.$r['id'].'&stage='.$x,'lead_stage',$r['id'].'|'.$x);?><option value="<?=e($u)?>"><?=$x?></option><?php endforeach;?></select></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
